  | 'INSTITUTIONAL_INVESTOR'
  | 'CORPORATE_BUYER'
  | 'INDIVIDUAL_BUYER'
  | 'DEVELOPER'
  | 'BUILDER'
  | 'LAND_OWNER'
  | 'JV_PARTNER'
  | 'BROKER'
  | 'REALTOR'
  | 'TOKENIZATION_PLATFORM'
  | 'DIGITAL_ASSET_INVESTOR'
  | 'INFLUENCER'
  | 'STRATEGIC_PARTNER';

export const ALL_PROSPECT_CATEGORIES: readonly ProspectCategory[] = [
  'INDIVIDUAL_INVESTOR',
  'ACCREDITED_INVESTOR_CANDIDATE',
  'FAMILY_OFFICE',
